import{_ as a,H as i,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"29 | 高性能：Kafka为什么性能那么好？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Kafka 分段与索引","slug":"kafka-分段与索引","link":"#kafka-分段与索引","children":[]},{"level":2,"title":"零拷贝","slug":"零拷贝","link":"#零拷贝","children":[]},{"level":2,"title":"批量操作的优势","slug":"批量操作的优势","link":"#批量操作的优势","children":[]},{"level":2,"title":"面试准备","slug":"面试准备","link":"#面试准备","children":[]},{"level":2,"title":"面试思路","slug":"面试思路","link":"#面试思路","children":[{"level":3,"title":"零拷贝","slug":"零拷贝-1","link":"#零拷贝-1","children":[]},{"level":3,"title":"page cache","slug":"page-cache","link":"#page-cache","children":[]},{"level":3,"title":"顺序写","slug":"顺序写","link":"#顺序写","children":[]},{"level":3,"title":"分区多影响写入性能","slug":"分区多影响写入性能","link":"#分区多影响写入性能","children":[]},{"level":3,"title":"分区过多如何解决？","slug":"分区过多如何解决","link":"#分区过多如何解决","children":[]},{"level":3,"title":"分区","slug":"分区","link":"#分区","children":[]},{"level":3,"title":"分段与索引","slug":"分段与索引","link":"#分段与索引","children":[]},{"level":3,"title":"批量处理","slug":"批量处理","link":"#批量处理","children":[]},{"level":3,"title":"批量处理高性能原因","slug":"批量处理高性能原因","link":"#批量处理高性能原因","children":[]},{"level":3,"title":"批量处理的兜底技术","slug":"批量处理的兜底技术","link":"#批量处理的兜底技术","children":[]},{"level":3,"title":"压缩","slug":"压缩","link":"#压缩","children":[]}]},{"level":2,"title":"面试思路总结","slug":"面试思路总结","link":"#面试思路总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"后端工程师的高阶面经/29｜高性能：Kafka为什么性能那么好？.md","filePath":"后端工程师的高阶面经/29｜高性能：Kafka为什么性能那么好？.md","lastUpdated":1795554391000}'),s={name:"后端工程师的高阶面经/29｜高性能：Kafka为什么性能那么好？.md"};function p(n,e,E,o,h,r){return i(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="_29-高性能-kafka为什么性能那么好" tabindex="-1">29 | 高性能：Kafka为什么性能那么好？ <a class="header-anchor" href="#_29-高性能-kafka为什么性能那么好" aria-label="Permalink to &quot;29 | 高性能：Kafka为什么性能那么好？&quot;">​</a></h1><p>你好，我是大明。今天我们来讨论一个问题，Kafka 的性能为什么那么好？</p><p>Kafka 的高性能话题也算是热点了，如果你面试的公司在并发量或者数据量上已经到了一定地步，那么面试的时候大概率逃不过这个问题。</p><p>大部分人面不好这个部分的原因只有一个：Kafka 为了实现高性能采用的手段太多了，以至于根本记不住。那么这一节课我就先聚焦在 Kafka 本身为了高性能做了哪些事情，下一节课我再从实践出发，告诉你怎么优化 Kafka 的性能。</p><p>让我们先从 Kafka 的一些基本知识开始说起。</p><h2 id="kafka-分段与索引" tabindex="-1">Kafka 分段与索引 <a class="header-anchor" href="#kafka-分段与索引" aria-label="Permalink to &quot;Kafka 分段与索引&quot;">​</a></h2><p>即便在同一个分区内部，Kafka 也进一步利用了分段日志和索引来加速消息查找。在 Kafka 内部，一个分区的日志是由很多个段（segment）组成的，每个段你可以理解成一个文件。同一个 topic 的文件就存放在以 topic 命名的目录下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/1.png" alt=""></a></p><p>为了快速找到对应的段文件，段日志文件使用了偏移量来命名。假如说一个文件的名字是N.log，那么就表示这个段文件里第一条消息的偏移量是 N + 1。</p><p>这里你就能猜到，Kafka 完全可以根据文件名来进行二分查找，从而快速定位到段文件。</p><p>为了加快段文件内的查找，每一个段文件都有两个索引文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个是偏移量索引文件，存储着部分消息偏移量到存储位置的映射，类似于 &lt;​offset,</span></span>
<span class="line"><span>position&gt; 这种二元组。这个 offset 不是全局 offset，是相对于这个文件第一条消息的偏</span></span></code></pre></div><ul><li>移量。也就是说假如第一条消息的全局偏移量是 1000，那么偏移量为 1002 的消息的索引</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项是 &lt;2, pos1&gt;。</span></span>
<span class="line"><span>一个是时间索引文件，存储着时间戳到存储位置的映射，类似于 &lt;​timestamp,</span></span>
<span class="line"><span>position&gt; 二元组。</span></span></code></pre></div><p>所以整个日志文件目录看上去是这样的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/2.png" alt=""></a></p><p>以这张图片为例，假如说要查找 topic 为 test_topic，分区为 1，偏移量为 20000 的消息，那么整个过程是这样的。</p><ol><li><p>在日志目录下找到名字为 test_topic_1 的子目录，里面就放着这个分区的消息日志文件。</p></li><li><p>在 test_topic_1 子目录下，根据文件名进行二分查找，可以确定 20000 这条消息应该放在010031.log 这个文件里面。</p></li><li><p>利用 010031.index 的内容进行二分查找，查找索引项。如果 20000 恰好有一个索引项</p></li></ol><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">20000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pos0&gt;，那么就读取 pos0 这个位置的数据。</span></span></code></pre></div><ol start="4"><li>如果 20000 没有对应的索引项，就找到比 20000 小的最接近 20000 的索引项，假如有</li></ol><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">19990</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，pos1&gt;，那么就从 pos1 往后遍历，找到 20000 对应的数据。</span></span></code></pre></div><p>对应的根据时间查找也差不多。这里要注意的是，索引文件放的只是部分消息对应的位置，因为 Kafka 希望索引文件能够装入内存。这种思想我之前提到过，我们在讨论 MySQL 索引的时候也是默认索引都在内存里面。</p><p>为了帮助你记忆，我整理成了三句话：topic 加分区定目录，偏移量定文件，索引定位置。记住这三句话就可以了。</p><h2 id="零拷贝" tabindex="-1">零拷贝 <a class="header-anchor" href="#零拷贝" aria-label="Permalink to &quot;零拷贝&quot;">​</a></h2><p>零拷贝（zero copy）是中间件广泛使用的一个技术，它能极大地提高中间件的性能。所谓的零拷贝，就是指没有 CPU 参与的拷贝。要理解零拷贝，要先从一般的读写操作开始讲起。假如说你现在要从磁盘读取内容，然后发送到网络上，那么基本流程如图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/3.png" alt=""></a></p><p>DMA （Direct Memory Access）是一个独立于 CPU 的硬件，所以我们不太在意 DMA 拷贝。NIC（Network Interface Card）就是指网卡。</p><p>这里面总共有四个步骤。</p><ol><li><p>应用进入内核态，从磁盘里读取数据到内核缓存，也就是读缓存。这一步应用就是发了一个指令，然后是 DMA 来完成的。</p></li><li><p>应用把读缓存里的数据拷贝到应用缓存里，这个时候切换回用户态。</p></li><li><p>应用进入内核态，把应用缓存里的数据拷贝到内核缓存里，也就是写缓存。</p></li><li><p>应用把数据从写缓存拷贝到 NIC 缓存里，这一步应用也就是发了一个指令，DMA 负责执行。</p></li></ol><p>而这里面总共有四次内核态与用户态的切换。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/4.png" alt=""></a></p><p>为什么要那么复杂，能不能不经过应用缓存，直接让磁盘读到内核缓存，然后内核缓存直接写到 NIC 缓存？这样不是非常完美吗？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/5.png" alt=""></a></p><p>也可以，而这就是零拷贝，对应的内核态 - 用户态切换，也只剩下了两次。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/6.png" alt=""></a></p><p>那么和最原始的操作比起来，零拷贝少了两次内核态与用户态的切换，还少了两次 CPU 拷贝。但是零拷贝本身还是要用到 DMA 拷贝。</p><h2 id="批量操作的优势" tabindex="-1">批量操作的优势 <a class="header-anchor" href="#批量操作的优势" aria-label="Permalink to &quot;批量操作的优势&quot;">​</a></h2><p>批量操作在高性能中间件里面也很常见。那么批量操作的优势究竟在哪里呢？主要体现在两个方面：一个是更少的系统调用和内核态与用户态的切换，还有一个是高效利用网络带宽。</p><p>我给你举一个例子，客户端每次都只发一个请求到服务端上，如今要发 100 个请求。现在客户端用了零拷贝技术，那么客户端发送 100 个请求，需要 100 次系统调用，200 次内核态与用户态的切换。而如果客户端一次性发送 100 个请求，那么它只需要 1 次系统调用，2 次内核态与用户态的切换。</p><p>在网络传输的时候，每一次发送都有一个固定开销，比如说协议头的部分，这个开销大小和具体的协议设计有关。假如说每个请求大小是 1KB，在网络传输的时候，分 100 次传输 1KB 和1 次传输 100KB，后者也是明显快很多的。前者需要传输 100 次协议头，而后者只需要传输 1次协议头。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/7.png" alt=""></a></p><p>当然，这是指应用层协议，如果是底层协议，比如 TCP，这方面也能节省一些，但是效果不如应用层协议好。</p><h2 id="面试准备" tabindex="-1">面试准备 <a class="header-anchor" href="#面试准备" aria-label="Permalink to &quot;面试准备&quot;">​</a></h2><p>准备 Kafka 高性能的面试，你还可以在公司内部了解一些信息。</p><ul><li><p>公司有没有因为分区或者 topic 太多导致 Kafka 性能衰退的案例？如果有，当时是怎么解决的？</p></li><li><p>公司内部的 Kafka 用的是机械硬盘还是固态硬盘？</p></li><li><p>公司内部的 Kafka 能撑住的并发量是多大？你的业务并发量是多大？</p></li><li><p>公司内部还有没有别的中间件也使用了类似的优化技术？</p></li><li><p>你在业务中有没有使用批量处理的技术来优化系统性能？如果有，具体是怎么做的？</p></li></ul><p>在面试中，比较好的策略是你根据自己对不同中间件的了解进行横向对比。比如说聊到 WAL的时候，把它和 MySQL、Redis 进行对比。这样能够凸显你对系统设计原则有深刻的理解。</p><p>当你和面试官聊到了下面这些话题的时候，你都可以尝试引导到这节课的话题下。</p><ul><li><p>你们聊到了 WAL 和 AOF，可以提及 Kafka 利用了类似的技术。</p></li><li><p>你们聊到操作系统的基本原理，系统调用、文件 IO 等，你就可以提及零拷贝，批量处理技术在 Kafka 中的应用。</p></li><li><p>你们聊到了并发优化的内容，那么可以用分区作为例子解释缩小并发粒度的好处。</p></li><li><p>你们聊到其他中间件采用了后面我列举的技术，那么你就可以和 Kafka 对比，深入阐述相关原理。</p></li><li><p>你们聊到了 Kafka 消息怎么存储，那么你就可以从性能的角度解释 Kafka 的分段和索引的优点。</p></li></ul><p>当然，面试官不一定直接问你为什么 Kafka 性能那么高，他也可能有多种问法。</p><ul><li><p>你们公司的 Kafka 性能怎样？怎么做到的？</p></li><li><p>Kafka 为什么要用零拷贝？</p></li><li><p>分区太多为什么会导致 Kafka 性能衰退？</p></li><li><p>Kafka 为什么要用压缩技术？</p></li><li><p>Kafka 是怎么查找到特定偏移量的消息的？</p></li></ul><p>这一类问题，你都可以用后面的内容来回答。</p><h2 id="面试思路" tabindex="-1">面试思路 <a class="header-anchor" href="#面试思路" aria-label="Permalink to &quot;面试思路&quot;">​</a></h2><p>Kafka 本身使用了很多手段来保证高性能，包括零拷贝、page cache（页缓存）、顺序读写、分区分段与索引、批量处理、压缩。其中零拷贝和顺序读写最重要，是一定要能回答出来的。</p><h3 id="零拷贝-1" tabindex="-1">零拷贝 <a class="header-anchor" href="#零拷贝-1" aria-label="Permalink to &quot;零拷贝&quot;">​</a></h3><p>前面你已经了解了什么是零拷贝，那么你在回答的时候就可以介绍零拷贝是如何运作的，然后再总结零拷贝的优势。</p><ul><li>零拷贝是中间件设计的通用技术，是指完全没有 CPU 参与的读写操作。我以从磁盘读数据，然后写到网卡上为例介绍一下。首先，应用程序发起系统调用，这个系统调用会读取磁盘的数据，读到内核缓存里面。同时，磁盘到内核缓存是 DMA 拷贝。然后再从内核缓存拷贝到 NIC 缓存中，这个过程也是 DMA 拷贝。这样就完成了整个读写操作。和普通的读取磁盘再发送到网卡比起来，零拷贝少了两次 CPU 拷贝，和两次内核态与用户态的切换。</li></ul><p>正常来说，你在回答里面不需要介绍普通的读取磁盘再发送的流程，不过如果面试官问了，你就可以按照前置知识里面的内容来回答。这里还有可能引申到操作系统相关的基本知识，面试前你也不要忘了复习。</p><p>然后你再补充一句，引出 page cache 的内容。</p><ul><li>这里说的内核缓存，在 linux 系统上其实就是 page cache。</li></ul><h3 id="page-cache" tabindex="-1">page cache <a class="header-anchor" href="#page-cache" aria-label="Permalink to &quot;page cache&quot;">​</a></h3><p>相信你对 page cache 并不陌生，前面我们接触过很多次了。Kafka 把数据写入到 page cache而不是直接刷新到磁盘上，有效减少了真实的 IO 操作次数。</p><p>另外一方面，Kafka 是基于 JVM 的，所以直接操作 page cache 能够避开 JVM 的垃圾回收。同时也能充分利用操作系统对 page cache 的优化。</p><ul><li>Kafka 充分利用了 page cache。Kafka 写入的时候只是写入到了 page cache，这几乎等价于一个内存写入操作，然后依靠异步刷新把数据刷新到磁盘上。而 page cache 是可以存放很多数据的，也就是说 Kafka 本身调用了很多次写入操作之后，才会真的触发 IO 操作，提高了性能。而且，Kafka 是基于 JVM 的，那么利用 page cache 也能缓解垃圾回收的压力。大多数跟 IO 操作打交道的中间件都有类似的机制，比如说 MySQL、Redis。</li></ul><p>你在这里可以适当引导一下，把话题引导到消息丢失上。</p><ul><li>不过使用 page cache 的缺陷就是如果消息还没刷新到磁盘上，服务器就宕机了，那么整个消息就丢失了。</li></ul><h3 id="顺序写" tabindex="-1">顺序写 <a class="header-anchor" href="#顺序写" aria-label="Permalink to &quot;顺序写&quot;">​</a></h3><p>在写操作里面，我们一般默认写是很慢的。但是实际上，写操作分成顺序写和随机写，我们认为写操作很慢，那都是随机写，而顺序写本身并不慢，所以你要先指出顺序写的性能。</p><ul><li>在计算机里面，普遍认为写很慢，但是实际上是随机写很慢，但是顺序写并不慢。即便是机械硬盘的顺序写也并不一定会比固态硬盘的顺序写慢。</li></ul><p>然后补充 Kafka 充分利用了顺序写。</p><ul><li>Kafka 在写入数据的时候就充分利用了顺序写的特性。它针对每一个分区，有一个日志文件WAL（write-ahead log），这个日志文件是只追加的，也就是顺序写的，因此发消息的性能会很好。MySQL、Redis 和其他消息中间件也采用了类似的技术。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/8.png" alt=""></a></p><p>紧接着你再补充一点业界早期的讨论。</p><ul><li>所以早期的时候业界就有人做过实验，一台 Kafka 服务器，把磁盘从机械硬盘切换到固态硬盘，性能虽然有提升，但是并不明显。在固态硬盘很贵的情况下，并不划算。</li></ul><p>接下来你可以从两个角度刷亮点：分区多影响写入性能和如何解决分区多问题。</p><h3 id="分区多影响写入性能" tabindex="-1">分区多影响写入性能 <a class="header-anchor" href="#分区多影响写入性能" aria-label="Permalink to &quot;分区多影响写入性能&quot;">​</a></h3><p>你应该注意到， Kafka 是每一个分区都有一个日志文件，万一你有很多分区呢？也就是说，如果分区特别多，就可能导致 Kafka 的写性能衰退。</p><ul><li><p>但是 Kafka 的顺序写要求的是分区内部顺序写，不同的分区之间就不是顺序写的。所以如果一个 topic 下的分区数量不合理，偏多的话，写入性能是比较差的。</p></li><li><p>举个例子，假如说要写入 100M 的数据，如果只有一个分区，那就是直接顺序写入 100M。但是如果有 100 个分区，每个分区写入 1M，它的性能是要差很多的。因为一个 topic 至少有一个分区，topic 多也会影响 Kafka 的性能。最好是在创建 topic 的时候就规划好分区，但是如果没规划好，还是得考虑解决。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/9.png" alt=""></a></p><p>这个回答里你提到了一个点，就是分区设置不合理，所以面试官就会追问你如何估计分区数量。这个知识你已经在前面第 25 讲学过了，记得复习一下。</p><p>最后一句话，也是你引导面试官追问怎么解决分区或者 topic 过多的问题。</p><h3 id="分区过多如何解决" tabindex="-1">分区过多如何解决？ <a class="header-anchor" href="#分区过多如何解决" aria-label="Permalink to &quot;分区过多如何解决？&quot;">​</a></h3><p>我们从分区过多和 topic 过多的角度分别去讨论。</p><p>如果是分区过多的话很好办，你只需要不使用其中的一些分区就可以了。</p><ul><li>如果某个 topic 分区太多了用不上，就可以考虑不用其中的一些分区。假设说我们现在有32 个分区，但是事实上业务本身用不上那么多分区，那么就可以考虑要求发送者只将消息发送到特定的 16 个分区上。当然，能够直接创建新 topic 是最好的。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/10.png" alt=""></a></p><p>topic 过多的问题，要稍微棘手一点，你可以考虑合并 topic。</p><ul><li>topic 过多的话，可以考虑合并一些 topic，但这也是看业务的。比如说最开始的设计是某个主业务下的子业务都有一个 topic，那么可以考虑这些子业务合并使用一个 topic，然后在里面用 type 等字段来标记是归属于哪个子业务的。</li></ul><p>有时候面试官可能会问，究竟多少个分区才算多，或者多少个分区才会导致性能下降呢？这里我给你一个阿里云中间件团队测试的结论。</p><ul><li><p>多少分区才算多，以及多少分区才会引起性能下降，这和 topic 本身有关，也和业务有关。</p></li><li><p>不过之前阿里云中间件团队测试过，在一个 topic 八个分区的情况下，超过 64 个 topic 之后，Kafka 性能就开始下降了。</p></li></ul><p>如果有兴趣，你也可以在你们公司的 Kafka 上执行一下测试。</p><h3 id="分区" tabindex="-1">分区 <a class="header-anchor" href="#分区" aria-label="Permalink to &quot;分区&quot;">​</a></h3><p>分区本身就能带来性能的提升，分区的好处就是 Kafka 可以按分区来处理，减少并发竞争。</p><ul><li>Kafka 的分区机制也能提高性能。假如说现在 Kafka 没有分区机制，只有 topic，那么可以预计的是不管是读还是写，并发竞争都是 topic 维度的。而在引入了分区机制之后，并发竞争的维度就变成分区了。如果是操作不同的分区，那么完全不需要搞并发控制。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/11.png" alt=""></a></p><p>如果你在面试过程中和面试官讲到了并发优化的点，那么你可以用分区这个例子来解释可以通过缩小并发粒度来提高性能。</p><h3 id="分段与索引" tabindex="-1">分段与索引 <a class="header-anchor" href="#分段与索引" aria-label="Permalink to &quot;分段与索引&quot;">​</a></h3><p>分段与索引的基本概念我们已经学过了，所以你只需要根据我总结的三句话简单介绍分段与索引就可以。同时讲清楚如何查找到特定消息，因为查找过程本身就是一个亮点。</p><ul><li><p>在 Kafka 中，每一个分区都对应多个段文件，放在同一个目录下。Kafka 根据 topic 和分区就可以确定消息存储在哪个目录内。每个段文件的文件名就是偏移量，假设为 N，那么这个文件第一条消息的偏移量就是 N+1。所以 Kafka 根据偏移量和文件名进行二分查找，就能确定消息在哪个文件里。</p></li><li><p>然后每一个段文件都有一个对应的偏移量索引文件和时间索引文件。Kafka 根据这个索引文件进行二分查找，就很容易在文件里面找到对应的消息。如果目标消息刚好有这个索引项，那么直接读取对应位置的数据。如果没有，就找到比目标消息偏移量小的，最接近目标消息的位置，顺序找过去。整个过程非常像跳表。</p></li></ul><h3 id="批量处理" tabindex="-1">批量处理 <a class="header-anchor" href="#批量处理" aria-label="Permalink to &quot;批量处理&quot;">​</a></h3><p>批量处理是高并发和大数据的常见解决方案。Kafka 为了提高性能，引入端到端的批量发送机制。在发送端，Kafka 的客户端并不是一次只发送一条消息，而是发送一批消息（recordbatch）。简单来说，就是好几条消息合并在一起发送。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/12.png" alt=""></a></p><p>而在 broker 端，Kafka 在存储的时候也是按照批来处理的。你在回答的时候要先解释 Kafka批量处理的基本机制。</p><ul><li>Kafka 还采用了批量处理来提高性能。Kafka 的客户端在发送的时候，并不是说每来一条消息就发送到 broker 上，而是说聚合够一批再发送。而在 broker 这一端，Kafka 也是同样按照批次来处理的，显然即便同样是顺序写，一次性写入数据都要比分多次快很多。除了Kafka，很多高并发、大数据的中间件也采用类似的技术，比如说日志采集与上报就采用批量处理来提升性能。</li></ul><p>然后你可以从批量处理的高性能原因和兜底技术两个角度刷亮点。</p><h3 id="批量处理高性能原因" tabindex="-1">批量处理高性能原因 <a class="header-anchor" href="#批量处理高性能原因" aria-label="Permalink to &quot;批量处理高性能原因&quot;">​</a></h3><p>首先你要深入分析批量处理高性能的原因。</p><ul><li><p>批量处理能够提升性能的原因是非常直观的，有两方面。一方面是减少系统调用和内核态与用户态切换的次数。比方说 100 个请求发送出去，即便采用零拷贝技术，也要 100 次系统调用 200 次内核态与用户态切换。而如果是一次性发送的话，那么就只需要 1 次系统调用和 2 次内核态与用户态切换。</p></li><li><p>另外一方面，批量处理也有利于网络传输。在网络传输中，一个难以避免的问题就是网络协议自身的开销。比如说协议头开销。那么如果发送 100 次请求，就需要传输 100 次协议头。如果 100 个请求合并为一批，那就只需要一个协议头。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/13.png" alt=""></a></p><h3 id="批量处理的兜底技术" tabindex="-1">批量处理的兜底技术 <a class="header-anchor" href="#批量处理的兜底技术" aria-label="Permalink to &quot;批量处理的兜底技术&quot;">​</a></h3><p>那么多大批次比较合适呢？关键词就是要兜底。</p><ul><li>不过批次也要设计合理。正常来说批次总是越大越好，但是批次太大会导致一个后果，就是客户端难以凑够一个批次。比如说 100 条消息一批和 1000 条消息一批，后者肯定很难凑够一个批次。一般来说批量处理都是要兜底的，就是在固定时间内如果都没有凑够某个批</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>次，那么就直接发送。比如说 Kafka 里面生产者就可以通过 linger.ms 参数来控制生产</span></span></code></pre></div><ul><li>者最终等多长时间。时间到了，即便只有一条消息，生产者也会把消息发送到 broker 上。</li></ul><h3 id="压缩" tabindex="-1">压缩 <a class="header-anchor" href="#压缩" aria-label="Permalink to &quot;压缩&quot;">​</a></h3><p>为了进一步降低数据传输和存储的压力，Kafka 还启用了压缩功能。Kafka 的压缩机制很特别。正常我们会认为如果 Kafka 支持压缩，那么应该是生产者压缩，发送到 broker 之后，broker 解压缩。然后 broker 压缩，发送到消费者之后，消费者解压缩。</p><p>Kafka 是彻底地端到端，就是生产者压缩之后发送到 broker，broker 直接存储。当 broker 推送到消费者的时候，消费者解压缩。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/14.png" alt=""></a></p><ul><li>Kafka 为了进一步降低网络传输和存储的压力，还对消息进行了压缩。这种压缩是端到端的压缩，也就是生产者压缩，broker 直接存储压缩后的数据，只有消费者才会解压缩。它带来的好处就是，网络传输的时候传输的数据会更少，存储的时候需要的磁盘空间也更少。当然，缺点就是压缩还是会消耗 CPU。如果生产者和消费者都是 CPU 密集型的应用，那么这种压缩机制反而加重了它们的负担。</li></ul><p>最后我们点出 CPU 密集型应用在使用 Kafka 的时候还面临着压缩数据竞争 CPU 资源的问题。不过在业界，CPU 密集型的应用非常少，会使用到 Kafka 的 CPU 密集型应用就更少了。</p><h2 id="面试思路总结" tabindex="-1">面试思路总结 <a class="header-anchor" href="#面试思路总结" aria-label="Permalink to &quot;面试思路总结&quot;">​</a></h2><p>最后我来总结一下这节课的要点。通过 Kafka 的分段与索引技术，我们了解到一个消息是怎么被存储的，还有消息是怎么查找的。这里还引入了一个新概念——零拷贝技术，你需要记住相比传统 IO 它独特的优势。</p><p>在回答 Kafka 为什么性能这么好这个问题的时候，你要从零拷贝、page cache、顺序写、分区、分段与索引、批量处理、压缩这几个角度回答。而如果你记不住这么多内容，那么记住零拷贝、顺序写这两个也可以。</p><p>我也建议你从横向角度去分类，比如写下零拷贝再写下使用了零拷贝的相应的中间件。这样能够加深你的理解，你在面试的时候也可以用这个知识来刷亮点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%90%8E%E7%AB%AF%E5%B7%A5%E7%A8%8B%E5%B8%88%E7%9A%84%E9%AB%98%E9%98%B6%E9%9D%A2%E7%BB%8F/images/29/15.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，请你来思考两个问题。</p><ul><li><p>Kafka 用到的这些优化技术，很多中间件也用到了，你能举几个例子吗？</p></li><li><p>我在分区里面讲到分区可以用来缩小并发粒度，减轻并发竞争，你还见过类似的技术吗？或者你有没有尝试在工作中使用类似的技术来优化自己的业务并发性能？</p></li></ul><p>欢迎你把你的答案分享在评论区，也欢迎你把这节课的内容分享给需要的朋友，我们下节课再见！</p>`,128)])])}const B=a(s,[["render",p]]);export{g as __pageData,B as default};
